export const MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION = 'lattice.managed_review_final_proposal.v1' as const;
export const MANAGED_REVIEW_CLAUDE_JSON_SCHEMA_MAX_BYTES = 16 * 1024;

